#include <genesis.h>

/* Animation row indexes. */
#define HERO_ANIM_IDLE 0
#define HERO_ANIM_WALK 1
#define HERO_ANIM_JUMP 2
#define HERO_ANIM_FALL 3
#define HERO_ANIM_COUNT 4

/* SGDK calls this after setting the frame timer. Never modify resource data in ROM.
 * If the game has its own frame-change callback, call this helper from it instead. */
static inline void hero_on_frame_changed(Sprite *sprite)
{
    if (!sprite || !sprite->animation) return;

}

/* Installs the callback above. Call on animation transitions. */
static inline void hero_set_animation(Sprite *sprite, u16 animation)
{
    if (!sprite || animation >= HERO_ANIM_COUNT) return;
    SPR_setFrameChangeCallback(sprite, hero_on_frame_changed);
    SPR_setAnim(sprite, animation);
}

